// Cloudflare Worker entry (wrangler.jsonc "main"). Wraps the Worker that `opennextjs-cloudflare build` generates
// from the Next.js app (.open-next/worker.js) and adds the Cron Trigger handler for scheduled pulls.
// See https://opennext.js.org/cloudflare/howtos/custom-worker

// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- the file is missing until the first build, present after
// @ts-ignore: generated by `opennextjs-cloudflare build`, so it doesn't exist before the first build
import { default as handler } from "./.open-next/worker.js";

interface ExecutionContext {
  waitUntil(promise: Promise<unknown>): void;
  passThroughOnException(): void;
}
interface ScheduledController {
  scheduledTime: number;
  cron: string;
}
type Env = Record<string, unknown>;

const app = handler as { fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> };

const worker = {
  fetch: app.fetch,

  // Every 15 minutes (wrangler.jsonc "triggers"): ask the app to run a scheduled round. The app decides whether
  // one is due (Settings → Data sync) and answers when the round has finished, so the pull runs inside this cron
  // run, which may last up to 15 minutes, instead of being cut ~30 seconds after a response like Refresh is.
  async scheduled(_controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    // Proves to /api/sync/scheduled that the call comes from here (the app reads it from the same global scope).
    const token = crypto.randomUUID();
    (globalThis as { __cronToken?: string }).__cronToken = token;
    try {
      const res = await app.fetch(
        new Request("https://cron.internal/api/sync/scheduled", { method: "POST", headers: { "x-cron-token": token } }),
        env,
        ctx,
      );
      console.log(`[sync] scheduled round: HTTP ${res.status} ${await res.text()}`);
    } finally {
      if ((globalThis as { __cronToken?: string }).__cronToken === token) delete (globalThis as { __cronToken?: string }).__cronToken;
    }
  },
};

export default worker;
